import numpy as np
from treehfd import XGBTreeHFD


def _pair_weights(model):
    df = model.get_booster().trees_to_dataframe()
    weights = {}
    for _, t in df.groupby("Tree"):
        t = t.set_index("ID")
        rows = t.to_dict("index")
        root = t.index[0]
        # find root: node with suffix "-0"
        for nid in rows:
            if nid.endswith("-0"):
                root = nid
                break
        stack = [(root, {})]
        while stack:
            nid, feats = stack.pop()
            r = rows[nid]
            if r["Feature"] == "Leaf":
                items = list(feats.items())
                for i in range(len(items)):
                    for k in range(i + 1, len(items)):
                        a, ga = items[i]
                        b, gb = items[k]
                        key = (min(a, b), max(a, b))
                        weights[key] = weights.get(key, 0.0) + min(ga, gb)
                continue
            f = r["Feature"]
            try:
                fi = int(str(f).lstrip("f"))
            except ValueError:
                fi = list(model.get_booster().feature_names).index(f)
            nf = dict(feats)
            nf[fi] = nf.get(fi, 0.0) + float(r["Gain"])
            for ch in (r["Yes"], r["No"]):
                if ch in rows:
                    stack.append((ch, nf))
    return {k: v for k, v in weights.items() if k[0] != k[1]}


def decompose(model, X_train, X_test):
    hfd = XGBTreeHFD(model)
    hfd.fit(X_train, interaction_order=2, verbose=False)
    y_main, y_order2 = hfd.predict(X_test, verbose=False)
    comps = {(j,): y_main[:, j] for j in range(y_main.shape[1])}

    w = _pair_weights(model)
    ranked = sorted(w.items(), key=lambda kv: -kv[1])
    keep = max(1, int(np.ceil(len(ranked) * 0.5))) if ranked else 0
    selected = {k for k, _ in ranked[:keep]}

    for k, (a, b) in enumerate(hfd.interaction_list):
        key = (int(min(a, b)), int(max(a, b)))
        if key in selected:
            comps[key] = y_order2[:, k]
    return float(hfd.eta0), comps
